const game = new GF.Game({
  id:'harbor-courier', title:'Harbor Courier', width:960, height:540,
  palette:['#16385C','#4DC6D8','#FFF3C4','#FF7C63','#37A66A'], background:'#4DC6D8', seed:481516
});

const C={navy:'#16385C',water:'#4DC6D8',cream:'#FFF3C4',coral:'#FF7C63',green:'#37A66A',road:'#F6E2B4',ink:'#19344C',white:'#FFFDF1'};
const stops=[
  {name:'Lighthouse Café',color:'#FF7C63',icon:'☕',parcel:{x:155,y:405},target:{x:785,y:108},route:[{x:405,y:260},{x:335,y:432},{x:670,y:432},{x:785,y:108}]},
  {name:'Coral Market',color:'#37A66A',icon:'M',parcel:{x:155,y:125},target:{x:790,y:415},route:[{x:405,y:260},{x:335,y:76},{x:665,y:76},{x:790,y:415}]},
  {name:'Seabreeze Hotel',color:'#4DC6D8',icon:'H',parcel:{x:175,y:410},target:{x:785,y:270},route:[{x:405,y:270},{x:335,y:445},{x:670,y:445},{x:785,y:270}]}
];
const blocks=[
  {x:390,y:120,w:200,h:270,label:'Harbor Houses',color:'#FF7C63'},
  {x:635,y:150,w:105,h:105,label:'Café Lane',color:'#FFF3C4'},
  {x:650,y:330,w:105,h:95,label:'Market Hall',color:'#37A66A'},
  {x:75,y:225,w:170,h:105,label:'Post Office',color:'#FFF3C4'},
  {x:270,y:438,w:105,h:42,label:'Dock Crates',color:'#37A66A'}
];
function hitsBlock(x,y,r,b){
  const qx=Math.max(b.x,Math.min(x,b.x+b.w));
  const qy=Math.max(b.y,Math.min(y,b.y+b.h));
  const dx=x-qx,dy=y-qy;
  return dx*dx+dy*dy<r*r;
}
function driveHeld(input){
  return !!(input.keys.ArrowLeft||input.keys.ArrowRight||input.keys.ArrowUp||input.keys.ArrowDown||input.keys.KeyA||input.keys.KeyD||input.keys.KeyW||input.keys.KeyS);
}

const play={
  init(){this.runCount=0;},
  reset(){
    this.runCount=(this.runCount||0)+1;
    this.p={x:115,y:455,vx:0,vy:0,angle:-1.2};
    this.delivery=0; this.carry=false; this.timer=75; this.wp=0;
    this.assist=false; this.wasBlocked=false; this.detourDone=false;
    this.notice='DRIVE TO THE GLOWING PARCEL'; this.noticeT=3;
    this.musicT=0; this.sparkT=0; this.lastVX=0; this.lastVY=0;
    if(this.runCount>1) game.event('fresh_run_started',{run:this.runCount,resetScore:game.score});
  },
  objective(){
    const s=stops[this.delivery];
    if(!s) return {x:480,y:270};
    if(!this.carry) return s.parcel;
    return this.wp<s.route.length?s.route[this.wp]:s.target;
  },
  update(dt){
    const s=stops[this.delivery];
    if(!s) return;
    const p=this.p;
    this.timer=Math.max(0,this.timer-dt*2.8);
    this.noticeT=Math.max(0,this.noticeT-dt);
    this.musicT+=dt;
    if(this.musicT>.92){
      this.musicT=0;
      GF.Sfx.beep({freq:this.timer<18?610:350,to:this.timer<18?680:410,dur:.045,type:'triangle',vol:.05});
    }
    if(this.timer<15 && Math.floor((this.timer+dt*2.8)*2)!==Math.floor(this.timer*2)) GF.Sfx.beep({freq:760,dur:.04,type:'square',vol:.12});
    if(this.timer<=0){
      game.flash(C.coral,.4); game.shake(6,.28); GF.Sfx.noise({dur:.28,vol:.18,freq:240});
      game.gameOver({message:"TIME'S UP — DISPATCH MISSED"});
      return;
    }

    const input=game.input;
    const pressedDrive=driveHeld(input)||input.pressed('Space');
    if(pressedDrive && game.time>1.3) this.assist=true;
    let ix=(input.keys.ArrowRight||input.keys.KeyD?1:0)-(input.keys.ArrowLeft||input.keys.KeyA?1:0);
    let iy=(input.keys.ArrowDown||input.keys.KeyS?1:0)-(input.keys.ArrowUp||input.keys.KeyW?1:0);
    let goal=this.objective();
    if(this.carry && this.wp<s.route.length && GF.math.dist(p.x,p.y,goal.x,goal.y)<18){
      this.wp++;
      goal=this.objective();
    }
    let dx=0,dy=0;
    if(this.assist){
      dx=goal.x-p.x; dy=goal.y-p.y;
    }else if(ix||iy){dx=ix;dy=iy;}
    const len=Math.hypot(dx,dy);
    if(len>0){dx/=len;dy/=len;}
    const speed=this.assist?285:245;
    p.vx+=(dx*speed-p.vx)*Math.min(1,dt*8);
    p.vy+=(dy*speed-p.vy)*Math.min(1,dt*8);
    if(!len){p.vx*=Math.max(0,1-dt*5);p.vy*=Math.max(0,1-dt*5);}
    const ox=p.x,oy=p.y;
    p.x+=p.vx*dt; p.y+=p.vy*dt;
    let collided=false;
    for(const b of blocks){if(hitsBlock(p.x,p.y,13,b)){collided=true;break;}}
    if(collided){
      p.x=ox;p.y=oy;p.vx*=0;p.vy*=0;
      this.wasBlocked=true;
      if(this.carry && this.wp===0){this.wp=1;this.notice='BLOCKED — TAKING THE OPEN STREET!';this.noticeT=1.25;}
      else {this.notice='SOLID BUILDING — FIND A STREET GAP';this.noticeT=.7;}
      GF.Sfx.beep({freq:150,to:105,dur:.07,type:'square',vol:.09});
    }
    p.x=GF.math.clamp(p.x,28,932);p.y=GF.math.clamp(p.y,70,510);
    const vl=Math.hypot(p.vx,p.vy);
    if(vl>8) p.angle=Math.atan2(p.vy,p.vx);
    if(vl>150 && this.lastVX*p.vx+this.lastVY*p.vy<-4500 && this.sparkT<=0){
      game.burst(p.x,p.y,{count:4,speed:45,size:2,life:.25,colors:[C.cream],gravity:30});this.sparkT=.16;
    }
    this.sparkT-=dt;this.lastVX=p.vx;this.lastVY=p.vy;

    const active=this.objective();
    if(!this.carry && GF.math.dist(p.x,p.y,active.x,active.y)<29){
      this.carry=true;this.wp=0;
      const before=game.score; game.addScore(25);
      this.notice='PARCEL ABOARD — FOLLOW THE MATCHING BEACON!';this.noticeT=1.8;
      game.event('parcel_collected',{stop:this.delivery+1,before:before,after:game.score});
      game.event('courier_scooter_delivery_started',{stop:this.delivery+1,target:s.name,score:game.score});
      game.burst(p.x,p.y,{count:12,speed:82,size:3,life:.45,colors:[s.color,C.cream],gravity:95});
      GF.Sfx.beep({freq:480,to:720,dur:.13,type:'triangle',vol:.22});
    }else if(this.carry && this.wp>=s.route.length && GF.math.dist(p.x,p.y,s.target.x,s.target.y)<42){
      this.complete(s);
    }
  },
  complete(s){
    const before=game.score;
    game.addScore(100);
    this.carry=false; this.delivery++;
    game.shake(4,.16); game.flash(s.color,.35); game.hitStop(.08);
    game.burst(s.target.x,s.target.y,{count:30,speed:165,size:4,life:.8,colors:[s.color,C.cream,C.green,C.coral],gravity:155});
    GF.Sfx.noise({dur:.09,vol:.14,freq:900});
    GF.Sfx.melody([[660,.07],[880,.09],[1100,.14]],{type:'triangle',vol:.18});
    game.event('delivery_completed',{stop:this.delivery,name:s.name,before:before,after:game.score});
    if(this.wasBlocked && !this.detourDone){
      this.detourDone=true;
      game.event('route_detour_completed',{stop:this.delivery,route:'street-corridor'});
    }
    if(this.delivery>=3){
      game.event('third_delivery_completed',{deliveries:3,timerRemaining:Math.round(this.timer),score:game.score});
      game.win({message:'ALL THREE HARBOR DELIVERIES COMPLETE!'});
      return;
    }
    this.timer=Math.min(75,this.timer+4);
    this.notice='DELIVERED! +4 TIDE-CLOCK SECONDS';this.noticeT=2;
  },
  draw(ctx){
    const W=960,H=540;
    const bg=ctx.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#79DDE5');bg.addColorStop(1,'#35AEC7');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
    ctx.globalAlpha=.28;ctx.strokeStyle=C.cream;ctx.lineWidth=2;
    for(let y=25;y<H;y+=30){ctx.beginPath();for(let x=0;x<W;x+=48)ctx.quadraticCurveTo(x+24,y+4*Math.sin((x+y+game.time*18)/48),x+48,y);ctx.stroke();}
    ctx.globalAlpha=1;
    ctx.fillStyle=C.road;ctx.fillRect(42,60,856,430);ctx.fillStyle='#FFF8DD';ctx.fillRect(54,72,832,406);
    ctx.strokeStyle='#D4B67A';ctx.lineWidth=3;ctx.setLineDash([11,11]);
    ctx.beginPath();ctx.moveTo(255,82);ctx.lineTo(255,466);ctx.moveTo(72,425);ctx.lineTo(870,425);ctx.moveTo(72,102);ctx.lineTo(870,102);ctx.stroke();ctx.setLineDash([]);
    for(const b of blocks){
      GF.Draw.roundRect(ctx,b.x+4,b.y+6,b.w,b.h,13,'rgba(22,56,92,.22)');GF.Draw.roundRect(ctx,b.x,b.y,b.w,b.h,13,b.color);
      ctx.fillStyle='rgba(255,255,255,.35)';ctx.fillRect(b.x+12,b.y+12,b.w-24,10);
      GF.Draw.text(ctx,b.label,b.x+b.w/2,b.y+b.h/2,{size:13,color:C.ink,weight:'800'});
    }
    for(let i=0;i<stops.length;i++){
      const s=stops[i],active=i===this.delivery;ctx.globalAlpha=active?1:.38;ctx.strokeStyle=s.color;ctx.lineWidth=active?5:3;
      ctx.beginPath();ctx.arc(s.target.x,s.target.y,active?32:23,0,Math.PI*2);ctx.stroke();ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(s.target.x,s.target.y,12,0,Math.PI*2);ctx.fill();
      GF.Draw.text(ctx,s.icon,s.target.x,s.target.y+1,{size:13,color:'#fff'});if(active)GF.Draw.text(ctx,s.name,s.target.x,s.target.y-42,{size:14,color:C.ink,weight:'800'});ctx.globalAlpha=1;
    }
    const s=stops[this.delivery];
    if(s&&!this.carry){const q=s.parcel,pulse=1+Math.sin(game.time*5)*.1;ctx.save();ctx.translate(q.x,q.y);ctx.scale(pulse,pulse);GF.Draw.roundRect(ctx,-15,-12,30,24,4,s.color);ctx.fillStyle=C.cream;ctx.fillRect(-11,-3,22,4);ctx.restore();GF.Draw.text(ctx,'PARCEL',q.x,q.y-26,{size:12,color:C.ink});}
    if(s){const o=this.carry?s.target:s.parcel,p=this.p;let ax=o.x-p.x,ay=o.y-p.y,al=Math.hypot(ax,ay)||1;ax/=al;ay/=al;const ex=480+ax*425,ey=286+ay*205;ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(ex,ey,11+Math.sin(game.time*5)*2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.moveTo(ex+ax*15,ey+ay*15);ctx.lineTo(ex-ay*8,ey+ax*8);ctx.lineTo(ex+ay*8,ey-ax*8);ctx.fill();}
    const p=this.p;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.angle);ctx.fillStyle='rgba(22,56,92,.22)';ctx.beginPath();ctx.ellipse(-2,8,22,10,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle=C.ink;ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-14,0);ctx.lineTo(14,0);ctx.stroke();ctx.fillStyle=C.navy;ctx.beginPath();ctx.arc(-12,0,7,0,Math.PI*2);ctx.arc(14,0,7,0,Math.PI*2);ctx.fill();GF.Draw.roundRect(ctx,-8,-10,22,18,7,C.water);ctx.fillStyle=C.cream;ctx.fillRect(7,-6,10,4);if(this.carry&&s)GF.Draw.roundRect(ctx,-17,-13,13,12,2,s.color);ctx.restore();
    GF.Draw.roundRect(ctx,16,12,174,45,11,'rgba(22,56,92,.93)');GF.Draw.text(ctx,'TIDE-CLOCK',29,27,{size:11,color:C.cream,align:'left'});GF.Draw.text(ctx,Math.ceil(this.timer)+'s',177,37,{size:25,color:this.timer<15?C.coral:'#fff',align:'right'});
    GF.Draw.roundRect(ctx,202,12,340,45,11,'rgba(22,56,92,.93)');GF.Draw.text(ctx,this.carry?'DELIVER TO':'PICK UP FOR',216,27,{size:11,color:C.cream,align:'left'});GF.Draw.text(ctx,s?(this.carry?s.name:'STOP '+(this.delivery+1)+' • '+s.name):'RUN COMPLETE',528,37,{size:17,color:s?s.color:'#fff',align:'right'});
    GF.Draw.roundRect(ctx,554,12,186,45,11,'rgba(22,56,92,.93)');GF.Draw.text(ctx,'DELIVERIES',568,27,{size:11,color:C.cream,align:'left'});GF.Draw.text(ctx,this.delivery+' / 3',726,37,{size:20,color:'#fff',align:'right'});
    GF.Draw.roundRect(ctx,752,12,192,45,11,'rgba(22,56,92,.93)');GF.Draw.text(ctx,'SCORE',766,27,{size:11,color:C.cream,align:'left'});GF.Draw.text(ctx,String(game.score),930,37,{size:22,color:'#fff',align:'right'});
    if(this.noticeT>0)GF.Draw.text(ctx,this.notice,480,512,{size:16,color:C.ink,weight:'800'});
    GF.Draw.vignette(ctx,W,H,.15);
  }
};

game.add('play',play);
game.titleScreen({subtitle:'ARROWS / WASD DRIVE • collect parcels • beat the tide-clock'});
